import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 처리 유형 허용값
const ACTIONS = ['승인', '보류', '반려'];
// 본인 권한 범위: 기안자이거나 결재선에 포함된 결재자
const SCOPE_SQL = '(d.drafter_id = CAST(:userId AS bigint) OR EXISTS (SELECT 1 FROM approval_line s WHERE s.approval_document_id = d.approval_document_id AND s.approver_id = CAST(:userId AS bigint)))';

function pageOf(query: Record<string, unknown>) {
  const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
  let size = query['size'] === undefined || query['size'] === '' ? 20 : Number(query['size']);
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '페이지 값이 올바르지 않습니다.');
  }
  if (size > 200) {
    size = 200;
  }
  return { page, size };
}

function idOf(value: unknown): string {
  const text = String(value ?? '');
  if (!/^[0-9]+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID 형식이 올바르지 않습니다.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr029105X949722Controller {
  @Post('/approval-documents/:approvalDocumentId/process')
  @HttpCode(200)
  async processApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = idOf(req.params['approvalDocumentId']);
    const data = checks.inputOf(req.body);
    const actionType = String(data['actionType'] ?? '');
    if (!ACTIONS.includes(actionType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 유형이 올바르지 않습니다.');
    }
    const opinionRaw = data['opinion'];
    const opinion = opinionRaw === undefined || opinionRaw === null ? '' : String(opinionRaw).trim();
    if (actionType === '반려' && opinion === '') {
      throw new ApiError(422, 'REJECT_OPINION_REQUIRED', '반려 시에는 결재 의견을 입력해야 합니다.');
    }
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT d.approval_status AS "approvalStatus" FROM approval_document d WHERE d.approval_document_id = CAST(:id AS bigint) AND ' + SCOPE_SQL,
        { id, userId: user.id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      const status = String(docs[0]['approvalStatus']);
      if (status !== '결재대기' && status !== '진행중') {
        throw new ApiError(409, 'NOT_APPROVER_TURN', '현재 결재 처리를 할 수 없는 문서입니다.');
      }
      const pending = await db.query(
        'SELECT approval_line_id AS "lineId", approver_id AS "approverId" FROM approval_line WHERE approval_document_id = CAST(:id AS bigint) AND action_type IS NULL ORDER BY line_group, sequence_no',
        { id },
      );
      if (pending.length === 0 || String(pending[0]['approverId']) !== String(user.id)) {
        throw new ApiError(409, 'NOT_APPROVER_TURN', '본인의 결재 차례가 아닙니다.');
      }
      await db.execute(
        'UPDATE approval_line SET action_type = :actionType, opinion = :opinion, processed_at = now(), updated_at = now() WHERE approval_line_id = CAST(:lineId AS bigint)',
        { actionType, opinion: opinion === '' ? null : opinion, lineId: String(pending[0]['lineId']) },
      );
      let next = '진행중';
      if (actionType === '반려') {
        next = '반려';
      } else if (actionType === '보류') {
        next = '보류';
      } else if (pending.length === 1) {
        next = '완료';
      }
      if (next === '완료') {
        // 가정: 마지막 결재자 승인 시 완료 일시를 현재 시각으로 기록
        await db.execute(
          'UPDATE approval_document SET approval_status = :next, completed_at = now(), updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)',
          { next, id },
        );
      } else {
        await db.execute(
          'UPDATE approval_document SET approval_status = :next, updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)',
          { next, id },
        );
      }
      return { approvalStatus: next };
    });
  }

  @Post('/approval-documents/:approvalDocumentId/withdraw')
  @HttpCode(200)
  async withdrawApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = idOf(req.params['approvalDocumentId']);
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT d.approval_status AS "approvalStatus" FROM approval_document d WHERE d.approval_document_id = CAST(:id AS bigint) AND d.drafter_id = CAST(:userId AS bigint)',
        { id, userId: user.id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      const status = String(docs[0]['approvalStatus']);
      const done = await db.query(
        'SELECT approval_line_id AS "lineId" FROM approval_line WHERE approval_document_id = CAST(:id AS bigint) AND action_type IS NOT NULL',
        { id },
      );
      if ((status !== '결재대기' && status !== '진행중') || done.length > 0) {
        throw new ApiError(409, 'WITHDRAW_NOT_ALLOWED', '다음 결재자가 이미 처리했거나 회수할 수 없는 상태의 문서입니다.');
      }
      await db.execute(
        "UPDATE approval_document SET approval_status = '회수', updated_at = now() WHERE approval_document_id = CAST(:id AS bigint)",
        { id },
      );
      return { approvalStatus: '회수' };
    });
  }

  @Get('/approval-documents')
  async listApprovalDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const { page, size } = pageOf(query);
    const params: Record<string, unknown> = { userId: user.id, limit: size, offset: page * size };
    let where = ' WHERE ' + SCOPE_SQL;
    const status = String(query['approvalStatus'] ?? '');
    if (status !== '') {
      where += ' AND d.approval_status = :approvalStatus';
      params['approvalStatus'] = status;
    }
    const startDate = String(query['startDate'] ?? '');
    if (startDate !== '') {
      where += ' AND d.submitted_at >= CAST(:startDate AS date)';
      params['startDate'] = startDate;
    }
    const endDate = String(query['endDate'] ?? '');
    if (endDate !== '') {
      where += ' AND d.submitted_at < CAST(:endDate AS date) + 1';
      params['endDate'] = endDate;
    }
    const drafter = String(query['drafterId'] ?? '');
    if (drafter !== '') {
      if (!/^[0-9]+$/.test(drafter)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '기안자 값이 올바르지 않습니다.');
      }
      where += ' AND d.drafter_id = CAST(:drafterId AS bigint)';
      params['drafterId'] = drafter;
    }
    const scheduled = String(query['scheduledOnly'] ?? '');
    if (scheduled === 'true') {
      where += " AND d.approval_status IN ('결재대기', '진행중') AND EXISTS (SELECT 1 FROM approval_line l WHERE l.approval_document_id = d.approval_document_id AND l.approver_id = CAST(:userId AS bigint) AND l.action_type IS NULL AND NOT EXISTS (SELECT 1 FROM approval_line e WHERE e.approval_document_id = l.approval_document_id AND e.action_type IS NULL AND (e.line_group < l.line_group OR (e.line_group = l.line_group AND e.sequence_no < l.sequence_no))))";
    }
    return transaction(async (db) => {
      const counted = await db.query('SELECT COUNT(*) AS "total" FROM approval_document d' + where, params);
      const items = await db.query(
        'SELECT d.approval_document_id AS "approvalDocumentId", d.document_number AS "documentNumber", d.title AS "title", d.approval_status AS "approvalStatus", d.drafter_id AS "drafterId", d.submitted_at AS "submittedAt" FROM approval_document d' + where + ' ORDER BY d.approval_document_id DESC LIMIT :limit OFFSET :offset',
        params,
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }

  @Get('/approval-documents/:approvalDocumentId')
  async getApprovalDocument(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = idOf(req.params['approvalDocumentId']);
    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT d.approval_document_id AS "approvalDocumentId", d.title AS "title", d.body AS "body", d.approval_status AS "approvalStatus" FROM approval_document d WHERE d.approval_document_id = CAST(:id AS bigint) AND ' + SCOPE_SQL,
        { id, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }

  @Get('/approval-lines')
  async listApprovalLines(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const { page, size } = pageOf(query);
    const rawId = String(query['approvalDocumentId'] ?? '');
    if (rawId === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서는 필수입니다.');
    }
    const id = idOf(rawId);
    return transaction(async (db) => {
      const docs = await db.query(
        'SELECT d.approval_document_id AS "approvalDocumentId" FROM approval_document d WHERE d.approval_document_id = CAST(:id AS bigint) AND ' + SCOPE_SQL,
        { id, userId: user.id },
      );
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재문서를 찾을 수 없습니다.');
      }
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM approval_line WHERE approval_document_id = CAST(:id AS bigint)',
        { id },
      );
      const items = await db.query(
        'SELECT approver_id AS "approverId", line_group AS "lineGroup", sequence_no AS "sequenceNo", action_type AS "actionType", opinion AS "opinion", processed_at AS "processedAt" FROM approval_line WHERE approval_document_id = CAST(:id AS bigint) ORDER BY line_group, sequence_no LIMIT :limit OFFSET :offset',
        { id, limit: size, offset: page * size },
      );
      return { items, page, size, total: Number(counted[0]['total']) };
    });
  }
}

