import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  Select,
  DateInput,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const STATUSES: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const ACTIONS: [string, string][] = [
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
];

function Detail({ id, role, notify, onChanged, onClose }: { id: number; role: string; notify: (text: string) => void; onChanged: () => void; onClose: () => void }) {
  const doc = useData<Row>(() => call('GET', `/approval-documents/${id}`, role), [id]);
  const lines = useData<Page>(() => call<Page>('GET', '/approval-lines', role, undefined, { approvalDocumentId: id, size: 200 }), [id]);
  const [actionType, setActionType] = useState('');
  const [opinion, setOpinion] = useState('');
  const status = String(doc.data?.['approvalStatus'] ?? '');
  const open = status === '결재대기' || status === '진행중';

  async function process() {
    if (actionType === '') {
      throw new Error('처리 유형을 선택해 주세요.');
    }
    if (actionType === '반려' && opinion.trim() === '') {
      throw new Error('반려 시에는 결재 의견을 입력해 주세요.');
    }
    await call('POST', `/approval-documents/${id}/process`, role, { actionType, opinion });
    notify('결재 처리를 했습니다.');
    setActionType('');
    setOpinion('');
    doc.reload();
    lines.reload();
    onChanged();
  }

  async function withdraw() {
    await call('POST', `/approval-documents/${id}/withdraw`, role, {});
    notify('문서를 회수했습니다.');
    doc.reload();
    lines.reload();
    onChanged();
  }

  return (
    <Drawer title="결재 문서" onClose={onClose}>
      {doc.error !== '' && <ErrorText text={doc.error} />}
      {doc.data && (
        <Pairs
          items={[
            ['문서 제목', String(doc.data['title'] ?? '')],
            ['결재 진행 상태', <Badge value={doc.data['approvalStatus']} />],
            ['문서 본문', String(doc.data['body'] ?? '')],
          ]}
        />
      )}
      <h2>결재선</h2>
      {lines.error !== '' && <ErrorText text={lines.error} />}
      <DataTable
        columns={[
          { key: 'approverId', label: '결재자', render: (r) => <RefName table="employee" role={role} value={r['approverId']} /> },
          { key: 'lineGroup', label: '결재선 구분' },
          { key: 'sequenceNo', label: '결재 순서' },
          { key: 'actionType', label: '처리 유형', render: (r) => <Badge value={r['actionType']} /> },
          { key: 'opinion', label: '결재 의견' },
          { key: 'processedAt', label: '처리 일시', render: (r) => <DateText value={r['processedAt']} time /> },
        ]}
        rows={lines.data?.items ?? []}
        empty="결재선이 없습니다."
      />
      {open && (
        <>
          <h2>결재 처리</h2>
          <Form onSubmit={process} submit="처리">
            <Field label="처리 유형" required>
              <Select value={actionType} onChange={setActionType} options={ACTIONS} />
            </Field>
            <Field label="결재 의견" wide hint="반려 시 필수">
              <TextInput value={opinion} onChange={setOpinion} multiline />
            </Field>
          </Form>
          <Form onSubmit={withdraw} submit="회수" danger note="기안자만 다음 결재자가 처리하기 전에 회수할 수 있습니다." />
        </>
      )}
    </Drawer>
  );
}

export default function FnSfr029105X949722Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [drafterId, setDrafterId] = useState<number | string>('');
  const [page, setPage] = useState(0);
  const [applied, setApplied] = useState<Row>({});
  const [selected, setSelected] = useState<number | null>(null);

  const list = useData<Page>(
    () => call<Page>('GET', '/approval-documents', role, undefined, { ...applied, page, size: 20 }),
    [applied, page],
  );
  const scheduled = useData<Page>(
    () => call<Page>('GET', '/approval-documents', role, undefined, { scheduledOnly: true, size: 5 }),
    [],
  );

  function search() {
    setPage(0);
    setApplied({ approvalStatus: status, startDate, endDate, drafterId });
  }

  function reset() {
    setStatus('');
    setStartDate('');
    setEndDate('');
    setDrafterId('');
    setPage(0);
    setApplied({});
  }

  function changed() {
    list.reload();
    scheduled.reload();
  }

  const columns = [
    { key: 'documentNumber', label: '문서번호' },
    { key: 'title', label: '문서 제목' },
    { key: 'approvalStatus', label: '결재 진행 상태', render: (r: Row) => <Badge value={r['approvalStatus']} /> },
    { key: 'drafterId', label: '기안자', render: (r: Row) => <RefName table="employee" role={role} value={r['drafterId']} /> },
    { key: 'submittedAt', label: '상신 일시', render: (r: Row) => <DateText value={r['submittedAt']} time /> },
  ];

  return (
    <div className="bento">
      <section className="box span-3">
        <h2>결재 예정</h2>
        <strong>{scheduled.data?.total ?? 0}</strong>
      </section>
      <section className="box span-3">
        <h2>조회 문서</h2>
        <strong>{list.data?.total ?? 0}</strong>
      </section>
      <section className="box span-8">
        <h2>결재 문서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="결재 진행 상태">
            <Select value={status} onChange={setStatus} options={STATUSES} />
          </Field>
          <Field label="조회 시작일">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="기안자">
            <LookupSelect table="employee" role={role} value={drafterId} onChange={setDrafterId} />
          </Field>
        </Filters>
        <Band total={list.data?.total} />
        {list.error !== '' && <ErrorText text={list.error} />}
        <DataTable
          columns={columns}
          rows={list.data?.items ?? []}
          onRowClick={(r) => setSelected(Number(r['approvalDocumentId']))}
          empty="문서가 없습니다."
        />
        <Pager page={page} size={20} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        {scheduled.error !== '' && <ErrorText text={scheduled.error} />}
        <DataTable
          columns={[
            { key: 'title', label: '문서 제목' },
            { key: 'approvalStatus', label: '상태', render: (r: Row) => <Badge value={r['approvalStatus']} /> },
          ]}
          rows={scheduled.data?.items ?? []}
          onRowClick={(r) => setSelected(Number(r['approvalDocumentId']))}
          empty="결재 예정 문서가 없습니다."
        />
      </section>
      {selected !== null && (
        <Detail id={selected} role={role} notify={notify} onChanged={changed} onClose={() => setSelected(null)} />
      )}
    </div>
  );
}
